import React, { useEffect, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography } from '@mui/material';
import InputLabel from '@mui/material/InputLabel';
import { name } from 'dayjs/locale/en-gb';
import { axios } from '../../utils/axios';
import { IMAGE_URL } from '../../utils/config';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import GoBackButton from '../../components/goBackButton/GoBackButton';
import InputField from '../../components/input/inputField';
import useResponsive from '../../hooks/useResponsive';

export default function EditPrivilegeData() {
  const navigate = useNavigate();
  const location = useLocation();
  const [privilegeCategory, setPrivilegeCategory] = useState('');
  const [decscribe, setDecscribe] = useState('');
  // const [imageFile, setImageFile] = useState(null);
  // const [imagepreview, setImagepreview] = useState(null);
  const isAddButtonDisabled = !privilegeCategory || !decscribe;
  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm');
  const [editId, setEditId] = useState(0)

  useEffect(() => {
    if (location?.state) {
      const { categories, descs } = location?.state;
      setPrivilegeCategory(categories);
      setDecscribe(descs);
      // setImageFile(IMAGE_URL + icon);
      // setImagepreview(IMAGE_URL + icon);
    }
  }, [location?.state]);
  if (!location?.state)
    return null;
  // const { process, id, categories, descs, catid, cate } = location?.state || { types: "", process: "", id: "", categories: {}, descs: "", privilegeid: "", catid: "", cate: "" };
  const { types, process } = location?.state || { types: "", process: ""};

  const backtouser = () => {
    // navigate(`/dashboard/privilegedata}`, { state: { types } });
    navigate(-1)
  };

  const updatePrivilegeCategory = async (id) => {
    // setEditId(id)
    // const editIds = `${editId}`
    try {
      if(location?.state?.id) { // update methd
        const ids = location?.state?.id;
      const res = await axios.put(`module/admin/privilegeCategory/${ids}`, {
        name: privilegeCategory,
        description: decscribe,
      });

      if (res.status === 200) {
        // navigate('/dashboard/privilegeCategory', { state: { types } });
        // navigate(`/dashboard/privilegedata?id=${id}`, { state: { types } })
          navigate(-1)
          GenerateToastConfig(res.data.message, "success");
      } else {
        GenerateToastConfig(res.data.message);
      }
    } else { // create method

      const res = await axios.post(`module/admin/privilegeCategory?privilegeId=${id}`, {
        name: privilegeCategory,
        description: decscribe,
      });

      if (res.status === 200) {
        // navigate(`/dashboard/privilegedata?id=${id}`, { state: { types } });
        navigate(-1)
      } else {
        GenerateToastConfig(res.data.message);
      }

    }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  return (
    <>
      <Helmet>
        <title> {`${process} Privilege Data`} </title>
      </Helmet>

      <Card sx={{ padding: '20px 10px', margin: '30px 0px' }}>
        <Grid container sx={{ borderBottom: '1px solid #dbe0e4', padding: '10px 0px' }}>
          <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
            <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
              {i18?.LISTINGPAGE?.EDIT_PRIVILEGE_DATA || "Edit Privilege Data"}
            </Typography>
            <GoBackButton
              label={i18?.LISTINGPAGE?.GO_BACK|| "Go Back"}
              onClick={backtouser}
              icon="icon-park-twotone:back"
            />
          </Grid>
        </Grid>

        <Grid container={!isMobile} sx={{ marginTop: '10px' }}>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputField
              label={i18?.LISTINGPAGE?.PRIVILEGE_NAME || "Privilege Name"}
              sx={{ margin: '10px 0px', width: '100%' }}
              name="FirstName"
              value={privilegeCategory}
              onChange={(e) => setPrivilegeCategory(e.target.value)}
            />
          </Grid>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputField
              label={i18?.LISTINGPAGE?.PRIVILEGE_DESCRIPTION || "Privilege Description"}
              sx={{ margin: '10px 0px', width: '100%' }}
              name="LastName"
              value={decscribe}
              onChange={(e) => setDecscribe(e.target.value)}
            />
          </Grid>
        </Grid>

        <Grid container justifyContent="flex-end" sx={{ marginTop: '10px', padding: '0px 5px' }}>
          {process === 'Edit' && (
            <Button variant="contained" disabled={isAddButtonDisabled} onClick={() => updatePrivilegeCategory()}>
              {i18?.LISTINGPAGE?.UPDATE || "Update"}
            </Button>
          )}
        </Grid>
      </Card>
    </>
  );
}
